def row_sum(grid, row):
    if row < 0:
        raise IndexError("row index must not be negative")
    if row >= len(grid):
        return 0
    return sum(grid[row])

def transpose(grid, fill=0):
    width = max((len(row) for row in grid), default=0)
    return [[row[i] if i < len(row) else fill for row in grid] for i in range(width)]

def col_sum(grid, column):
    if column < 0:
        raise IndexError("column index must not be negative")
    return sum(row[column] if column < len(row) else 0 for row in grid)
